INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Portfolio', 'Developed a responsive portfolio website to showcase my projects.', '/projectImages/alexanderhellsten.se.png', 'Aug 2025', ARRAY['JavaScript', 'React', 'Tailwind CSS', 'Node.js', 'Git', 'Next.js']::text[], 'Web Application', 'https://github.com/ThiccTapeman/alexanderhellsten.se', 'https://alexanderhellsten.se', 0);
INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Wordpress API Integration', 'Application that uses Next.js as frontend and Wordpress as backend, can edit/remove/add new posts in a wordpress project.', '/projectImages/wordpress.alexanderhellsten.se.png', 'Sept 2025', ARRAY['JavaScript', 'React', 'Tailwind CSS', 'Node.js', 'Git', 'Next.js', 'Wordpress API']::text[], 'Web Application', 'https://github.com/ThiccTapeman/wordpress-test', 'https://wordpress.alexanderhellsten.se', 1);
INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Lego Game', 'A 3D physics puzzle game made in Unity where you build the level and guide a rolling ball into the goal by shaping its path and momentum.', '/projectImages/lego-game.png', 'Jan 2023', ARRAY['Unity', 'Blender', 'C#']::text[], 'Game', 'https://github.com/ThiccTapeman/lego-game', '', 2);
INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Mea Culpa', 'A 2D platformer created for a 2-day game jam. The project was developed by a team of four: two developers, one artist, and one composer. I was responsible for core gameplay programming and contributed to overall design and technical implementation throughout the jam.', '/projectImages/mea-culpa.png', 'Jan 9 - Jan 11 2026', ARRAY['Unity', 'C#', 'Git', 'Aseprite']::text[], 'Game', 'https://github.com/ThiccTapeman/jamegam-50', 'https://thicctapeman.itch.io/mea-culpa', 3);
INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Twilight Vail', 'A 2D platformer created during a 7-day game jam. I assembled and led a small team, taking responsibility for core programming, technical direction, and overall organization. I also drove the initial concept and design, and implemented key gameplay systems throughout the development period.', '/projectImages/twilight-vail2.png', 'Jan 18 - Jan 25 2026', ARRAY['Unity', 'C#', 'Git', 'Aseprite']::text[], 'Game', 'https://github.com/ThiccTapeman/jamegam-56', 'https://thicctapeman.itch.io/twilight-veil', 4);
INSERT INTO "projects" ("projectName", "projectDescription", "projectImage", "projectDate", "projectTechnologies", "projectType", "projectGithub", "projectHomepage", "position") VALUES ('Backpack Keybinds', 'A Minecraft mod that allows players to customize keybinds for individual backpacks, providing more control over inventory management.', '/projectImages/backpack-keybinds.png', 'July 30 2026 - Present', ARRAY['Java', 'Aseprite', 'Neoforge']::text[], 'Mod', '', 'https://modrinth.com/mod/backpack-keybinds', 5);
